//! zstd frames produced by the VENDORED libzstd 1.5.6 that the archiver links.
//!
//! Generated by `rust/cryptref/zstd_vectors.cpp` with the parameters
//! `C_Zstd.cpp` sets -- compression level, and `windowLog` paired with
//! `enableLongDistanceMatching` when a window log is given.
//!
//! The direction under test is decode: `zstd-sys` bundles **1.5.7** while the
//! repository vendors **1.5.6**, so adopting the crate is a version bump. The
//! frame format is unchanged between them, and this is what proves it for the
//! archives that already exist rather than assuming it from the changelog.
//!
//! Encoder output is deliberately not compared. 1.5.7 is free to choose
//! different matches, `-mzstd` is in no `-m` preset and no fingerprint case,
//! so nothing recorded moves.

use darc_codecs::zstd::{self, Params};

const VECTORS: &[(&str, usize, &str)] = &[
    ("text-l3", 4096, "28b52ffd60000f8d0100840274686520717569636b2062726f776e20666f78206a756d7073206f766572206c617a7920646f67200100a8fef25519"),
    ("text-l19", 4096, "28b52ffd60000f8d0100840274686520717569636b2062726f776e20666f78206a756d7073206f766572206c617a7920646f67200100a8fef25519"),
    ("text-ldm", 4096, "28b52ffd60000f8d0100840274686520717569636b2062726f776e20666f78206a756d7073206f766572206c617a7920646f67200100a8fef25519"),
    ("runs", 2048, "28b52ffd6000074d00001041410100fbff000b"),
    ("random", 2048, ""),
    ("empty", 0, "28b52ffd2000010000"),
];

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2).map(|i| u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap()).collect()
}

fn original(name: &str, len: usize) -> Vec<u8> {
    match name {
        n if n.starts_with("text") => {
            let w = ["the ", "quick ", "brown ", "fox ", "jumps ", "over ", "lazy ", "dog "];
            let mut v = Vec::with_capacity(len);
            let mut i = 0usize;
            loop {
                let s = w[i % 8].as_bytes();
                if v.len() + s.len() > len { break; }
                v.extend_from_slice(s);
                i += 1;
            }
            v.resize(len, b' ');
            v
        }
        "runs" => vec![b'A'; len],
        "random" => {
            let mut s: u32 = 12345;
            (0..len).map(|_| { s = s.wrapping_mul(1103515245).wrapping_add(12345); (s >> 16) as u8 }).collect()
        }
        "empty" => Vec::new(),
        other => panic!("no reconstruction for vector {other}"),
    }
}

#[test]
fn decodes_frames_written_by_the_vendored_1_5_6() {
    for &(name, len, hex) in VECTORS {
        let frame = unhex(hex);
        let out = zstd::decompress(&frame, len.max(1))
            .unwrap_or_else(|e| panic!("{name}: decompress failed with {e}"));
        assert_eq!(out, original(name, len), "{name}: decoded bytes differ");
    }
}

#[test]
fn round_trips_its_own_output() {
    for &(name, len, _) in VECTORS {
        let src = original(name, len);
        let params = Params { level: 3, window_log: 0, workers: 0 };
        let packed = zstd::compress(&src, params).expect("compress failed");
        let out = zstd::decompress(&packed, src.len().max(1)).expect("own output rejected");
        assert_eq!(out, src, "{name}: round-trip mismatch");
    }
}

#[test]
fn honours_the_long_distance_matching_pairing() {
    // C_Zstd.cpp turns on enableLongDistanceMatching only together with a
    // window log, never separately. Both settings must be accepted and produce
    // a decodable frame.
    let src = original("text", 4096);
    let packed = zstd::compress(&src, Params { level: 3, window_log: 20, workers: 0 })
        .expect("windowLog + LDM rejected");
    assert_eq!(zstd::decompress(&packed, src.len()).unwrap(), src);
}

#[test]
fn rejects_corrupt_frames_without_panicking() {
    // Reached through "arc t" on a damaged archive.
    let frame = unhex(VECTORS[0].2);
    let len = VECTORS[0].1;
    for cut in [0usize, 1, 4, 8, frame.len() / 3, frame.len() / 2, frame.len() - 1] {
        let _ = zstd::decompress(&frame[..cut.min(frame.len())], len);
    }
    for i in (0..frame.len()).step_by(11) {
        let mut bad = frame.clone();
        bad[i] ^= 0xff;
        let _ = zstd::decompress(&bad, len);
    }
}

#[test]
fn refuses_to_exceed_the_callers_capacity() {
    // A frame whose content size exceeds what the caller says is possible must
    // fail rather than grow the buffer on the strength of a header field.
    let (name, len, hex) = VECTORS[0];
    let frame = unhex(hex);
    assert!(
        zstd::decompress(&frame, len / 2).is_err(),
        "{name}: decoded past the stated capacity"
    );
}
